import * as THREE from 'three';
import {RoundedBoxGeometry} from './vendor/RoundedBoxGeometry.js';
export function buildBedroom(layout){
 const root=new THREE.Group(),architecture=new THREE.Group(),units=[],products=[],actions=[];root.add(architecture);
 const liner=new THREE.MeshStandardMaterial({color:'#eee7dc',roughness:.65}),metal=new THREE.MeshStandardMaterial({color:'#aeb2ae',metalness:.8,roughness:.22}),wall=new THREE.MeshStandardMaterial({color:'#f1eee6',roughness:.85});
 function box(parent,w,h,d,x,y,z,mat){const mesh=new THREE.Mesh(new RoundedBoxGeometry(w,h,d,2,Math.min(.003,w/8,h/8,d/8)),mat);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);return mesh;}
 function unit(id,name,w,h,d,x,y,z,normal,spec){const group=new THREE.Group();group.position.set(x,y,z);group.rotation.y=Math.atan2(normal[0],normal[2]);root.add(group);const finish=new THREE.MeshPhysicalMaterial({color:'#d6cfbd',roughness:.78,metalness:0,clearcoat:0,clearcoatRoughness:.8,envMapIntensity:.55});const section={name,spec,finish:true};const u={id,name,group,finish,section,defaultSample:'p06-02',definition:{width:w,height:h,depth:d,normal,origin:[x,y,z]},actions:[]};units.push(u);return u;}
 function carcass(u){const {width:w,height:h,depth:d}=u.definition,g=u.group,t=.018;for(const x of [-w/2+t/2,w/2-t/2])box(g,t,h,d,x,0,-d/2,u.finish);for(const y of [-h/2+t/2,h/2-t/2])box(g,w-t*2,t,d,0,y,-d/2,u.finish);box(g,w,h,t,0,0,-d+t/2,u.finish);}
 function act(u,node,type,travel){const a={unit:u,node,type,travel,open:false,value:0,initial:node.position.clone()};actions.push(a);u.actions.push(a);node.traverse(o=>{if(o.isMesh)o.userData.action=a});return a;}
 function door(u,x,w,h,y,hinge='left'){const p=new THREE.Group(),sign=hinge==='left'?1:-1;p.position.set(x-sign*w/2,y,0);u.group.add(p);box(p,w-.005,h-.006,.019,sign*w/2,h/2,.01,u.finish);act(u,p,'door',sign*-1.62);}
 function drawer(u,y,h,internal=false){const {width:w,depth:d}=u.definition,p=new THREE.Group(),ww=internal?w-.08:w,dd=internal?d-.06:d;p.position.set(0,y,internal?-.055:0);p.userData.internalDrawer=internal;u.group.add(p);box(p,ww-.007,h-.006,.02,0,0,.012,internal?liner:u.finish);box(p,ww-.075,.014,dd-.06,0,-h/2+.025,-dd/2,liner);for(const x of [-ww/2+.04,ww/2-.04])box(p,.012,h-.055,dd-.06,x,0,-dd/2,liner);box(p,ww-.075,h-.055,.012,0,0,-dd+.035,liner);act(u,p,'drawer',Math.min(.4,dd*.72));}
 function product(id,name,members,normal){const group=new THREE.Group();root.add(group);const p={id,name,displayName:name,group,members,definition:{normal},section:{name,finish:true,spec:[...new Set(members.map(u=>u.section.spec))].join(' ')},actions:members.flatMap(u=>u.actions)};for(const u of members){group.add(u.group);u.product=p;u.group.traverse(o=>{if(o.isMesh){o.userData.unit=u;o.userData.product=p}});}products.push(p);return p;}
 const {width:W,height:H,depth:D,wardrobeWidth:WW,wardrobeHeight:WH,seatHeight:SH}=layout,wardrobes=[];
 const bayX=WW+(W-WW)/2,roomName=layout.roomName||'Bedroom 1',prefix=layout.idPrefix||'bed1',wardrobeSections=layout.wardrobeSections||4;
 for(let i=0;i<wardrobeSections;i++){const w=WW/wardrobeSections,h=WH,u=unit(prefix+'-wardrobe-'+i,'Wardrobe',w,h,D,w*(i+.5),h/2,0,[0,0,1],layout.wardrobeSpec||'Wardrobe: front arrangement 12 × 7 ft, with continuous full-height shutters. Internal drawers sit behind the shutters. Default finish: matte Burma Teak wood-grain mica. Shelves, hanger rail and two drawers per two-door section; concealed lighting provision. Internal arrangement is illustrative.');carcass(u);for(const y of [-h/2+.55,0,h/2-.32])box(u.group,w-.05,.018,D-.05,0,y,-D/2,liner);const rod=new THREE.Mesh(new THREE.CylinderGeometry(.012,.012,w-.10,16),metal);rod.rotation.z=Math.PI/2;rod.position.set(0,h/2-.16,-D/2);u.group.add(rod);for(const y of [-h/2+.16,-h/2+.36])drawer(u,y,.18,true);u.defaultSample='p06-02';door(u,-w/4,w/2,h,-h/2);door(u,w/4,w/2,h,-h/2,'right');wardrobes.push(u);}
 product('wardrobe',roomName+' wardrobe',wardrobes,[0,0,1]);
 const lofts=[];const widths=layout.loftWidths||[...Array(10).fill(.4572),.3048];let edge=0;for(let i=0;i<widths.length;i++){const w=widths[i],h=H-WH,u=unit(prefix+'-loft-'+i,'Loft',w,h,D,edge+w/2,WH+h/2,0,[0,0,1],layout.loftSpec||'Loft: front arrangement 16 × 3 ft. Shuttering-only supply scope; surrounding enclosure is shown for the preview.');carcass(u);door(u,0,w,h,-h/2);lofts.push(u);edge+=w;}product('loft',roomName+' loft',lofts,[0,0,1]);
 if(layout.baySeating!==false){
 const seat=unit('bed1-seat','Bay-window seating',W-WW,SH,D,bayX,SH/2,0,[0,0,1],'Bay-window seating beneath the window. Model reference: 4 ft wide × 1.5 ft high. Earlier quotation: 4 × 1.25 ft cushion box with hidden locker, cushion excluded. Final height and storage mechanism await confirmation; no price or quoted measurement changed.');carcass(seat);door(seat,-(W-WW)/4,(W-WW)/2,SH,-SH/2);door(seat,(W-WW)/4,(W-WW)/2,SH,-SH/2,'right');const seatP=product('bay-seat','Bay-window seating',[seat],[0,0,1]);
 const upholstery=new THREE.MeshStandardMaterial({color:'#c4b8a3',roughness:.95});box(seat.group,layout.seatClearWidth-.035,.055,D-.045,-layout.sideWidth/2,SH/2+.0275,-D/2,upholstery).userData.cushion=true;
 // Cushion is a visual reference only and remains excluded from the quotation.
 seat.group.traverse(o=>{if(o.isMesh)o.userData.product=seatP});
 const side=unit('bed1-side','Bay-side storage',D,WH-SH,layout.sideWidth,W-layout.sideWidth,SH+(WH-SH)/2,-D/2,[-1,0,0],'Narrow storage beside the bay-window seat, facing into the bay. Open shelves above and below a drawer, matching the source arrangement. Identification and pricing pending confirmation.');carcass(side);for(const y of [-.39,.07,.47])box(side.group,D-.04,.018,layout.sideWidth-.025,0,y,-layout.sideWidth/2,liner);drawer(side,-.05,.383);product('bay-side-storage','Bay-side shelves & drawer',[side],[-1,0,.35]);
 }
 box(architecture,W+.1,.06,2.5,W/2,-.045,.62,new THREE.MeshStandardMaterial({color:'#dcd4c4',roughness:.8}));
 // Wall behind cabinets is closed; the bay is deliberately a window opening.
 box(architecture,layout.baySeating===false?W:WW,WH,.05,(layout.baySeating===false?W:WW)/2,WH/2,-D-.04,wall);box(architecture,W,H-WH,.05,W/2,WH+(H-WH)/2,-D-.04,wall);if(layout.baySeating!==false)box(architecture,W-WW,SH,.05,bayX,SH/2,-D-.04,wall);
 if(layout.baySeating!==false){
 const windowW=layout.seatClearWidth-.045,windowH=WH-SH-.065,cx=WW+layout.seatClearWidth/2,z=-D-.01;
 const sky=new THREE.MeshBasicMaterial({color:'#dce8e6'});box(architecture,windowW,windowH,.012,cx,SH+(WH-SH)/2,z-.02,sky);const frame=new THREE.MeshStandardMaterial({color:'#eff0e9',metalness:.25,roughness:.3});for(const x of [cx-windowW/2,cx,cx+windowW/2])box(architecture,.025,windowH,.045,x,SH+(WH-SH)/2,z,frame);for(const y of [SH+.032,WH-.032])box(architecture,windowW,.025,.045,cx,y,z,frame);
 }
 root.updateMatrixWorld(true);return {root,architecture,units,products,actions,update(dt){for(const a of actions){a.value=THREE.MathUtils.damp(a.value,a.open?1:0,9,dt);if(a.type==='drawer')a.node.position.z=a.initial.z+a.travel*a.value;else a.node.rotation.y=a.travel*a.value;}}};
}
